<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
/** Phase 4 read-only aggregate model. SEO never queries Leads tables. */
final class Estandar_SEO_Conversion_Analytics {
    public static function get_organic_conversion_summary( array $period, array $filters = array() ): array {
        $period = self::period( $period ); if ( empty( $period ) ) { return self::empty( 'invalid_period', array() ); }
        $cache = 'seo_conversion_' . md5( wp_json_encode( array( $period, $filters ) ) ); $cached = function_exists( 'wp_cache_get' ) ? wp_cache_get( $cache, 'estandar_seo' ) : false; if ( is_array( $cached ) ) { return $cached; }
        $seo = Estandar_SEO_Repository::conversion_rows( $period, $filters );
        $commercial = class_exists( 'Estandar_Leads_SEO_Analytics' ) ? Estandar_Leads_SEO_Analytics::get_organic_conversion_summary( $period, $filters ) : array( 'status' => 'leads_unavailable', 'dimensions' => array(), 'warnings' => array( 'leads_plugin_unavailable' ) );
        if ( ! empty( $filters['project'] ) ) {
            $project_landings = array(); foreach ( (array) $commercial['dimensions'] as $row ) { $project_landings[(string) ( $row['landing_url'] ?? '' )] = true; }
            $seo = array_values( array_filter( $seo, static function( $row ) use ( $project_landings ) { return isset( $project_landings[(string) ( $row['landing_url'] ?? '' )] ); } ) );
        }
        $by_landing = array(); foreach ( (array) $commercial['dimensions'] as $row ) { $by_landing[$row['landing_url']] = $row; }
        foreach ( $seo as $row ) { $landing = $row['landing_url']; $c = $by_landing[$landing] ?? array( 'project_id' => '', 'google_organic_leads' => 0, 'classified_leads' => 0, 'qualified_leads' => 0, 'commercial_results_available' => 0 ); $by_landing[$landing] = array_merge( $c, $row ); }
        $dimensions = array_values( $by_landing ); foreach ( $dimensions as &$row ) { self::rates( $row ); } unset( $row );
        $fresh = self::freshness( $seo ); $result = array( 'status' => $commercial['status'] === 'available' ? ( $fresh['stale'] ? 'stale' : 'available' ) : $commercial['status'], 'period' => $period, 'timezone' => Estandar_SEO_Service::commercial_timezone()->getName(), 'dimensions' => $dimensions, 'seo_metrics' => self::sum( $dimensions, array( 'clicks', 'impressions' ) ), 'commercial_metrics' => self::sum( $dimensions, array( 'google_organic_leads', 'classified_leads', 'qualified_leads', 'commercial_results_available' ) ), 'conversion_rates' => self::total_rates( $dimensions ), 'freshness' => $fresh, 'attribution_scope' => array( 'source' => 'independent_aggregates', 'scope' => 'landing_aggregate', 'exact_query_known' => false ), 'warnings' => array_values( array_unique( array_merge( (array) ( $commercial['warnings'] ?? array() ), array( 'Search Console clicks and Leads are independent aggregates; they are not sessions or individual attribution.' ) ) ) ) );
        if ( function_exists( 'wp_cache_set' ) ) { wp_cache_set( $cache, $result, 'estandar_seo', 300 ); } return $result;
    }
    public static function get_landing_conversion_metrics( $url, array $period, array $filters = array() ): array { $filters['landing'] = $url; return self::get_organic_conversion_summary( $period, $filters ); }
    public static function get_project_organic_performance( $project_id, array $period, array $filters = array() ): array { $filters['project'] = $project_id; return self::get_organic_conversion_summary( $period, $filters ); }
    public static function get_query_landing_performance( $url, array $period, array $filters = array() ): array { $filters['landing'] = $url; $result = self::get_landing_conversion_metrics( $url, $period, $filters ); $result['dimensions'] = Estandar_SEO_Repository::conversion_rows( $result['period'], $filters, true ); $result['warnings'][] = 'Query metrics are associated with landing performance only, never a specific Lead.'; return $result; }
    private static function period( array $p ): array { $from = (string) ( $p['from'] ?? '' ); $to = (string) ( $p['to'] ?? '' ); return preg_match('/^\d{4}-\d{2}-\d{2}$/',$from) && preg_match('/^\d{4}-\d{2}-\d{2}$/',$to) && $from <= $to ? array( 'from'=>$from, 'to'=>$to ) : array(); }
    private static function rates( array &$r ): void { $r['lead_per_click_rate'] = ! empty($r['clicks']) ? round((int)$r['google_organic_leads']/(int)$r['clicks'], 4) : 0.0; $r['qualified_per_lead_rate'] = ! empty($r['google_organic_leads']) ? round((int)$r['qualified_leads']/(int)$r['google_organic_leads'],4) : 0.0; }
    private static function sum( array $rows, array $keys ): array { $out=array(); foreach($keys as $key){$out[$key]=array_sum(array_map(static function($r)use($key){return (float)($r[$key]??0);},$rows));} return $out; }
    private static function total_rates( array $rows ): array { $s=self::sum($rows,array('clicks','google_organic_leads','qualified_leads')); return array('lead_per_click_rate'=>$s['clicks'] ? round($s['google_organic_leads']/$s['clicks'],4):0.0,'qualified_per_lead_rate'=>$s['google_organic_leads'] ? round($s['qualified_leads']/$s['google_organic_leads'],4):0.0); }
    private static function freshness( array $seo ): array { $latest=''; foreach($seo as $r){if(($r['period_to']??'')>$latest)$latest=$r['period_to'];} $age=$latest ? max(0,(int)(new DateTimeImmutable('now',Estandar_SEO_Service::commercial_timezone()))->diff(new DateTimeImmutable($latest,Estandar_SEO_Service::commercial_timezone()))->format('%r%a')*-1):null; return array('latest_commercial_date'=>$latest,'age_days'=>$age,'stale'=>$age===null || $age>Estandar_SEO_Service::stability_delay_days()+2); }
    private static function empty(string $s,array $p):array{return array('status'=>$s,'period'=>$p,'timezone'=>Estandar_SEO_Service::commercial_timezone()->getName(),'dimensions'=>array(),'seo_metrics'=>array(),'commercial_metrics'=>array(),'conversion_rates'=>array(),'freshness'=>array(),'attribution_scope'=>array('scope'=>'landing_aggregate','exact_query_known'=>false),'warnings'=>array());}
}
